<?php
/*
 * Default configuration. Do not edit this file:
 * copy it to config.php and override only what you need.
 */
$env = static fn (string $k, $default = null) => ($v = getenv($k)) === false || $v === '' ? $default : $v;

return [
    // Which database servers users may log into.
    // Keep this list short: an open host field turns the tool into a proxy.
    // Docker: set PMF_DB_HOST / PMF_DB_PORT / PMF_DB_LABEL.
    //
    // SSL/TLS per server (optional):
    //   'ssl' => true,                        encrypt the connection
    //   'ssl_ca' => '/path/to/ca.pem',        CA that signed the server certificate ('' = system store)
    //   'ssl_verify' => true,                 check the server certificate (keep it on)
    //   'ssl_cert' => '…', 'ssl_key' => '…',  client certificate, when the server asks for one
    //   'ssl_choice' => true,                 let users change SSL on the login screen
    //
    // Look per server (optional):
    //   'color' => 'red',                     red | orange | amber | green | teal | blue | violet | pink
    //   'env' => 'production',                production | staging | development | local
    // A thin stripe of that color and the environment label stay visible in the app;
    // 'production' asks for confirmation before anything that writes.
    'servers' => [
        [
            'label' => $env('PMF_DB_LABEL', 'Local'),
            'host' => $env('PMF_DB_HOST', '127.0.0.1'),
            'port' => (int) $env('PMF_DB_PORT', 3306),
            'ssl' => filter_var($env('PMF_DB_SSL', false), FILTER_VALIDATE_BOOL),
        ],
    ],
    // Appearance defaults for every user (each user can still change them in
    // Settings unless 'ui_locked' is true):
    //   'theme' => monochrome | graphite | slate | spider | forest | contrast
    //   'mode' => light | dark | system, 'density' => compact | comfortable,
    //   'radius' => sharp | soft | round, 'fontSize' => 13..16, 'accent' => '#1d4ed8'
    // 'ui' => ['theme' => 'monochrome', 'density' => 'compact'],
    'ui' => [],
    'ui_locked' => false,

    // Allow typing any host on the login screen (off by default).
    'allow_custom_host' => false,

    // CA files users may pick on the login screen ("Other server…" or 'ssl_choice'),
    // by label. The browser only ever sees the labels.
    // 'ssl_ca_files' => ['Company CA' => '/etc/ssl/company-ca.pem'],
    'ssl_ca_files' => [],

    // Seconds to wait for the database server when connecting.
    'connect_timeout_seconds' => (int) $env('PMF_CONNECT_TIMEOUT', 10),

    // Block every statement that writes (INSERT, UPDATE, DDL...). The MySQL session
    // is also opened read-only, and KILL / statistics reset are refused.
    'read_only' => filter_var($env('PMF_READ_ONLY', false), FILTER_VALIDATE_BOOL),

    // Stop any statement after this many seconds (0 = no limit). Useful for a shared
    // or public installation. MySQL applies it to SELECT only.
    'query_timeout_seconds' => (float) $env('PMF_QUERY_TIMEOUT', 0),

    // Public demo only: user and password filled in on the sign-in screen, for example
    // ['user' => 'demo', 'password' => 'demo']. Ignored unless 'read_only' is true.
    // When set, only this user may sign in.
    'demo_login' => $env('PMF_DEMO_USER', '') !== ''
        ? ['user' => (string) $env('PMF_DEMO_USER', ''), 'password' => (string) $env('PMF_DEMO_PASSWORD', '')]
        : null,

    // AGPL-3.0: everyone who uses phpMyFlow can get its source code (link on the
    // sign-in screen). If you run a modified copy, point this to your source.
    'source_url' => (string) $env('PMF_SOURCE_URL', 'https://github.com/spiderjad/phpmyflow'),

    // SQL import: uploaded files go to a private temp folder (one per session,
    // deleted at the end or after a day). Prefer a folder outside the web root.
    'import_dir' => $env('PMF_IMPORT_DIR', ''), // '' = system temp dir
    'import_max_bytes' => 2147483648, // 2 GB

    // Export and import run as jobs of short requests: seconds of work per request.
    // Lower it on hosts with a short time limit; the browser asks for the next step.
    'job_step_seconds' => (float) $env('PMF_JOB_STEP_SECONDS', 3),

    // Max rows returned by a free SQL query.
    'max_result_rows' => 1000,

    // Login brute-force protection.
    'login_max_attempts' => (int) $env('PMF_LOGIN_MAX_ATTEMPTS', 5),
    'login_window_seconds' => 900,

    // Session idle timeout.
    // A minute before, the browser warns with a countdown ("Stay signed in" renews it).
    'session_idle_seconds' => (int) $env('PMF_SESSION_IDLE_SECONDS', 3600),

    // AI assistant. The key never reaches the browser.
    // provider: 'anthropic' | 'openai' (any OpenAI-compatible API: OpenAI, OpenRouter, Ollama, LM Studio...)
    'ai' => [
        'enabled' => filter_var($env('PMF_AI_ENABLED', false), FILTER_VALIDATE_BOOL),
        'provider' => $env('PMF_AI_PROVIDER', 'anthropic'),
        'api_key' => $env('PMF_AI_API_KEY', ''),
        'model' => $env('PMF_AI_MODEL', 'claude-sonnet-5-5'),
        'base_url' => $env('PMF_AI_BASE_URL', ''), // e.g. http://localhost:11434/v1 for Ollama
        'max_tokens' => 2000,
        'timeout_seconds' => 60,
    ],

    // Monitor. Optional user for the collector (collect.php / pseudo-cron).
    // See README "Monitor" for the minimal GRANTs. Credentials live only here.
    // 'monitor' => ['host' => '127.0.0.1', 'port' => 3306, 'user' => 'phpmyflow_monitor', 'password' => ''],

    // No cron on the host: take at most one sample per minute while the Monitor is open.
    'monitor_pseudo_cron' => filter_var($env('PMF_MONITOR_PSEUDO_CRON', false), FILTER_VALIDATE_BOOL),

    // Where history is stored ('' = server/data). Prefer a folder outside the web root.
    'monitor_data_dir' => $env('PMF_MONITOR_DATA_DIR', ''),

    // Fixed peak thresholds (otherwise automatic: mean + 3 standard deviations of the last hour).
    // 'monitor_peaks' => ['threads_running' => 20, 'qps' => 2000, 'threads_connected' => 200],

    // Alert thresholds per metric and optional webhook (slack | teams | generic).
    // 'monitor_alerts' => ['thresholds' => ['threads_running' => ['warn' => 10, 'crit' => 30]], 'webhook' => '', 'format' => 'generic'],
];
